const WHATSAPP='556792496064';
const whatsappUrl=(topic='duvidas')=>'https://wa.me/'+WHATSAPP+'?text='+encodeURIComponent(topic==='consultoria'?'Oi! Vim pelo site Endomonstro e quero saber como funciona a consultoria.':'Oi! Vim pelo site Endomonstro e quero tirar uma dúvida.');
const $=s=>document.querySelector(s);const quiz=$('#quiz-dialog'),info=$('#info-dialog');let step=0,answers=[],opener;
const questions=[{title:'O QUE VOCÊ PROCURA AGORA?',choices:[['autonomia','Aprender e fazer no meu ritmo'],['apoio','Conhecer um acompanhamento'],['indeciso','Ainda não sei']]},{title:'O QUE MAIS ATRAPALHA SUA ROTINA?',choices:[['direcao','Vejo muita dica e fico perdido'],['comida','Organizar compras e alimentação'],['social','Seguir a rotina nos fins de semana']]},{title:'COMO VOCÊ PREFERE COMEÇAR?',choices:[['pontual','Por um material menor'],['completo','Pelo curso completo'],['conversa','Conversando sobre acompanhamento']]},{title:'QUAL PRÓXIMO PASSO FAZ MAIS SENTIDO?',choices:[['aprender','Ver o que eu posso aprender'],['conversar','Saber como funciona a consultoria'],['comparar','Comparar as opções com calma']]}];
function event(name,detail={}){document.dispatchEvent(new CustomEvent('endomonstro:event',{detail:{name,...detail}}))}
function openDialog(dialog,trigger){opener=trigger;dialog.showModal();document.body.style.overflow='hidden'}
function closeDialog(dialog){dialog.close();dialog.querySelectorAll('iframe').forEach(f=>f.remove());document.body.style.overflow='';if(opener?.isConnected)opener.focus()}
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>closeDialog(b.closest('dialog'))));[quiz,info,$("#offer-dialog")].filter(Boolean).forEach(d=>{d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(d)});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})});
function renderQuestion(){const q=questions[step];$('#quiz-content').innerHTML=`<div class="quiz-progress" aria-hidden="true">${questions.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div><span class="quiz-count">PERGUNTA ${step+1} DE 4</span><h2 id="quiz-title" tabindex="-1">${q.title}</h2><div class="quiz-options">${q.choices.map(([value,label],i)=>`<button class="quiz-choice" data-answer="${value}"><span>${String.fromCharCode(65+i)}</span>${label}</button>`).join('')}</div>${step?'<button class="quiz-back">← Voltar uma pergunta</button>':'<small>A indicação considera suas preferências. Não é uma avaliação de saúde.</small>'}`;$('#quiz-title').focus();$('#quiz-content').querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{answers[step]=b.dataset.answer;answers.length=step+1;event('quiz_answer',{step:step+1,answer:b.dataset.answer});step++;step<questions.length?renderQuestion():renderResult()}));$('#quiz-content .quiz-back')?.addEventListener('click',()=>{step--;renderQuestion()})}
function resultFor(a){if(a[3]==='comparar')return'comparar';if(a[3]==='conversar'||a[2]==='conversa'||a[0]==='apoio')return'consultoria';if(a[2]==='pontual')return'essenciais';return'curso'}
function renderResult(){const result=resultFor(answers);const content={curso:{title:'SEU CAMINHO:<br> <em>ENDOMONSTRO.</em>',text:'Você quer aprender no seu ritmo. No meu curso, eu te ensino sobre comida, treino e hábitos. Bora conhecer?',cta:'Conhecer o curso',target:'#curso'},consultoria:{title:'SEU CAMINHO:<br> <em>UMA CONVERSA.</em>',text:'Você quer saber mais sobre acompanhamento. Fale com a minha equipe para entender como funciona e quanto custa.',cta:'Conhecer a consultoria',target:'#consultoria'},essenciais:{title:'UM PASSO<br> <em>DE CADA VEZ.</em>',text:`Você quer começar por uma coisa de cada vez. ${answers[1]==='comida'?'Cozinha da Tropa':answers[1]==='social'?'Rotina Social':'Guia Primeiros Passos'} é um dos materiais que estou preparando. Ainda não está à venda, mas você pode ver o que vem por aí.`,cta:'Conhecer os Essenciais',target:'#essenciais'},comparar:{title:'ESCOLHA<br> <em>COM CLAREZA.</em>',text:'Você quer olhar tudo com calma. Eu te mostro o curso e a consultoria lado a lado para ajudar na escolha.',cta:'Comparar os dois caminhos',target:'#caminhos'}}[result];$('#quiz-content').innerHTML=`<span class="quiz-count">SEU RESULTADO</span><h2 id="quiz-title" tabindex="-1">${content.title}</h2><p class="result-note">${content.text}</p><a class="button result-link" href="${document.body.classList.contains('content-page')?'index.html':''}${content.target}">${content.cta}<span aria-hidden="true">↗</span></a><button class="button outline" id="redo">Refazer as perguntas</button><small>A indicação usa somente suas respostas sobre preferências. Você pode escolher qualquer outro caminho.</small>`;$('#quiz-title').focus();$('.result-link').addEventListener('click',()=>{closeDialog(quiz);event('quiz_offer_click',{result});requestAnimationFrame(()=>{const target=$(content.target);target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true})})});$('#redo').addEventListener('click',()=>{step=0;answers=[];renderQuestion()});event('quiz_complete',{result})}
document.querySelectorAll('[data-quiz]').forEach(b=>b.addEventListener('click',()=>{closeMenu();step=0;answers=[];openDialog(quiz,b);renderQuestion();event('quiz_start')}));
const products={primeiros:{title:'PRIMEIROS PASSOS.',text:'Estou preparando um guia para te ajudar a organizar o começo e escolher seus primeiros passos.',detail:'Foco: organização e primeiros passos.'},cozinha:{title:'COZINHA DA TROPA.',text:'Estou preparando um material com ideias para compras e refeições simples, do jeito que mostro nos meus vídeos.',detail:'Foco: praticidade na alimentação do dia a dia.'},social:{title:'ROTINA SOCIAL.',text:'Estou preparando um material para te ajudar a pensar nas escolhas nas festas, nos encontros e na volta à rotina.',detail:'Foco: continuidade e vida social.'}};
document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',()=>{const p=products[b.dataset.product];$('#info-content').innerHTML=`<span class="soon">EM BREVE</span><h2 id="info-title">${p.title}</h2><p>${p.text}</p><p>${p.detail}</p><small>Ainda não está à venda. Vou avisar o preço, o conteúdo e a data quando estiver pronto.</small><a class="button" href="#curso" id="info-course">Enquanto isso, conheça o curso <span aria-hidden="true">↗</span></a>`;openDialog(info,b);$('#info-course').addEventListener('click',()=>closeDialog(info));event('essential_view',{product:b.dataset.product})}));
function openWhatsapp(trigger,topic='duvidas'){$('#info-content').innerHTML='<h2 id="info-title">'+(topic==='consultoria'?'BORA FALAR DA<br> <em>CONSULTORIA?</em>':'FICOU COM<br> <em>ALGUMA DÚVIDA?</em>')+'</h2><p>Minha equipe te ajuda a entender o curso, a consultoria e como começar.</p><p>Clique abaixo para abrir a conversa no WhatsApp. Você confere a mensagem antes de enviar.</p><a class="button" href="'+whatsappUrl(topic)+'" target="_blank" rel="noopener noreferrer">Conversar no WhatsApp <span aria-hidden="true">↗</span></a><small>+55 67 9249-6064 · Nenhuma mensagem é enviada sozinha.</small>';openDialog(info,trigger);event('whatsapp_interest',{topic})}
document.querySelectorAll('[data-consult]').forEach(b=>b.addEventListener('click',()=>openWhatsapp(b,'consultoria')));
document.querySelectorAll('[data-whatsapp]').forEach(b=>b.addEventListener('click',()=>openWhatsapp(b)));
$('[data-privacy]').addEventListener('click',e=>{$('#info-content').innerHTML='<h2 id="info-title">SUA PRIVACIDADE.</h2><p>O quiz funciona nesta página, sem pedir cadastro. Suas respostas ficam apenas na memória desta aba e são descartadas quando a página é recarregada.</p><p>Esta versão não possui formulários de captura nem ferramentas de publicidade ou análise instaladas. Uso o armazenamento da sessão do navegador apenas para não repetir o pop-up depois que ele aparece. Parâmetros de campanha presentes no endereço podem acompanhar o link para a Hotmart.</p><p>Ao abrir WhatsApp, Instagram, TikTok, YouTube ou Hotmart, passam a valer as políticas desses serviços. Ao pedir para assistir a um vídeo, a página carrega o player do Instagram, que pode usar cookies. A plataforma de hospedagem pode registrar dados técnicos necessários para servir e proteger a página.</p>';openDialog(info,e.currentTarget)});
function closeMenu(){$('#mobile-menu').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Abrir menu')}
$('.menu-toggle').addEventListener('click',()=>{const open=$('#mobile-menu').hidden;$('#mobile-menu').hidden=!open;$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});$('#mobile-menu').querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const params=new URLSearchParams(location.search);document.querySelectorAll('.checkout').forEach(a=>{const u=new URL(a.href);for(const key of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','src','sck']){const v=params.get(key);if(v)u.searchParams.set(key,v.slice(0,250))}a.href=u.href;a.addEventListener('click',()=>event('checkout_click',{product:'endomonstro'}))});

// A oferta usa apenas os itens já anunciados no curso. Não há desconto fictício.
const offerDialog=$('#offer-dialog');let offerShown=false;try{offerShown=sessionStorage.getItem('endo_offer_seen')==='1'}catch{}
function showTimedOffer(){if(offerShown||!offerDialog||document.body.classList.contains('content-page'))return;if(document.hidden||document.querySelector('dialog[open]')){setTimeout(showTimedOffer,2000);return}offerShown=true;try{sessionStorage.setItem('endo_offer_seen','1')}catch{}openDialog(offerDialog,document.activeElement);event('timed_offer_view')}
if(!offerShown&&!document.body.classList.contains('content-page'))setTimeout(showTimedOffer,60000);
document.querySelector('[data-offer-dismiss]')?.addEventListener('click',()=>closeDialog(offerDialog));
offerDialog?.querySelector('.checkout')?.addEventListener('click',()=>closeDialog(offerDialog));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(f=>f.setAttribute('aria-pressed',String(f===b)));let count=0;document.querySelectorAll('.video-card').forEach(c=>{c.hidden=b.dataset.filter!=='Todos'&&c.dataset.category!==b.dataset.filter;if(!c.hidden)count++});$('#video-count').textContent=count+' '+(count===1?'vídeo':'vídeos')}));
document.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.video;if(!/^[A-Za-z0-9_-]+$/.test(id))return;$('#info-content').replaceChildren();const title=document.createElement('h2');title.id='info-title';title.textContent=b.dataset.title;const frame=document.createElement('iframe');frame.src='https://www.instagram.com/reel/'+id+'/embed/';frame.title='Vídeo de Lucas C Prot: '+b.dataset.title;frame.className='instagram-player';frame.allow='encrypted-media; fullscreen; picture-in-picture';frame.referrerPolicy='strict-origin-when-cross-origin';const fallback=document.createElement('a');fallback.href='https://www.instagram.com/reel/'+id+'/';fallback.target='_blank';fallback.rel='noopener noreferrer';fallback.className='button';fallback.textContent='Abrir vídeo e comentários no Instagram ↗';const note=document.createElement('p');note.className='embed-note';note.textContent='Se o vídeo não carregar aqui, abra no Instagram. O player pode pedir login e usa as políticas do Instagram.';$('#info-content').append(title,frame,note,fallback);openDialog(info,b);event('video_play',{id})}));

